  1→import { useEffect, useState } from "react";
  2→import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
  3→import { useLoaderData, useFetcher, useNavigate } from "react-router";
  4→import { useAppBridge } from "@shopify/app-bridge-react";
  5→import {
  6→  Page,
  7→  Layout,
  8→  Card,
  9→  BlockStack,
 10→  InlineStack,
 11→  Text,
 12→  Badge,
 13→  Button,
 14→  TextField,
 15→  Checkbox,
 16→  Box,
 17→  Divider,
 18→} from "@shopify/polaris";
 19→import { authenticate } from "../shopify.server";
 20→import db from "../db.server";
 21→
 22→// ---------------------------------------------------------------------------
 23→// Types
 24→// ---------------------------------------------------------------------------
 25→
 26→interface LocalConfig {
 27→  displayMode: string;
 28→  position: string;
 29→  triggerType: string;
 30→  primaryColor: string;
 31→  successColor: string;
 32→  errorColor: string;
 33→  backgroundColor: string;
 34→  textColor: string;
 35→  borderRadius: string;
 36→  heading: string;
 37→  placeholder: string;
 38→  buttonText: string;
 39→  successMessage: string;
 40→  errorMessage: string;
 41→  showRecommender: boolean;
 42→  customCss: string;
 43→}
 44→
 45→// ---------------------------------------------------------------------------
 46→// Loader
 47→// ---------------------------------------------------------------------------
 48→
 49→export const loader = async ({ request }: LoaderFunctionArgs) => {
 50→  const { session } = await authenticate.admin(request);
 51→  const config = await db.widgetConfig.findUnique({ where: { shop: session.shop } });
 52→
 53→  return {
 54→    config: config ?? {
 55→      displayMode: "popup",
 56→      position: "bottom-right",
 57→      triggerType: "button",
 58→      primaryColor: "#000000",
 59→      successColor: "#16a34a",
 60→      errorColor: "#dc2626",
 61→      backgroundColor: "#ffffff",
 62→      textColor: "#111111",
 63→      borderRadius: "8",
 64→      heading: "Size Guide",
 65→      placeholder: "Select your size",
 66→      buttonText: "Find My Size",
 67→      successMessage: "This size should fit you well!",
 68→      errorMessage: "We couldn't determine your size. Please refer to the chart.",
 69→      showRecommender: true,
 70→      customCss: "",
 71→    },
 72→  };
 73→};
 74→
 75→// ---------------------------------------------------------------------------
 76→// Action
 77→// ---------------------------------------------------------------------------
 78→
 79→export const action = async ({ request }: ActionFunctionArgs) => {
 80→  const { session } = await authenticate.admin(request);
 81→  const formData = await request.formData();
 82→
 83→  try {
 84→    const data = {
 85→      displayMode: (formData.get("displayMode") as string) || "popup",
 86→      position: (formData.get("position") as string) || "bottom-right",
 87→      triggerType: (formData.get("triggerType") as string) || "button",
 88→      primaryColor: (formData.get("primaryColor") as string) || "#000000",
 89→      successColor: (formData.get("successColor") as string) || "#16a34a",
 90→      errorColor: (formData.get("errorColor") as string) || "#dc2626",
 91→      backgroundColor: (formData.get("backgroundColor") as string) || "#ffffff",
 92→      textColor: (formData.get("textColor") as string) || "#111111",
 93→      borderRadius: (formData.get("borderRadius") as string) || "8",
 94→      heading: (formData.get("heading") as string) || "Size Guide",
 95→      placeholder: (formData.get("placeholder") as string) || "Select your size",
 96→      buttonText: (formData.get("buttonText") as string) || "Find My Size",
 97→      successMessage: (formData.get("successMessage") as string) || "This size should fit you well!",
 98→      errorMessage: (formData.get("errorMessage") as string) || "We couldn't determine your size.",
 99→      showRecommender: formData.get("showRecommender") === "true",
100→      customCss: (formData.get("customCss") as string) || "",
101→    };
102→
103→    await db.widgetConfig.upsert({
104→      where: { shop: session.shop },
105→      update: data,
106→      create: { shop: session.shop, ...data },
107→    });
108→    return { ok: true, message: "Widget settings saved" };
109→  } catch (error) {
110→    return {
111→      error: error instanceof Error ? error.message : "An unexpected error occurred",
112→    };
113→  }
114→};
115→
116→// ---------------------------------------------------------------------------
117→// Sub-components
118→// ---------------------------------------------------------------------------
119→
120→function ColorPickerField({
121→  label,
122→  value,
123→  onChange,
124→}: {
125→  label: string;
126→  value: string;
127→  onChange: (v: string) => void;
128→}) {
129→  return (
130→    <Card>
131→      <BlockStack gap="200">
132→        <Text as="p" variant="bodyMd">{label}</Text>
133→        <InlineStack gap="200" blockAlign="center">
134→          <div
135→            style={{
136→              width: "32px",
137→              height: "32px",
138→              borderRadius: "6px",
139→              border: "1px solid #c9cccf",
140→              overflow: "hidden",
141→              flexShrink: 0,
142→              position: "relative",
143→              cursor: "pointer",
144→            }}
145→          >
146→            <input
147→              type="color"
148→              value={value}
149→              onChange={(e) => onChange(e.target.value)}
150→              style={{
151→                position: "absolute",
152→                inset: 0,
153→                opacity: 0,
154→                width: "100%",
155→                height: "100%",
156→                cursor: "pointer",
157→                padding: 0,
158→                border: "none",
159→              }}
160→            />
161→            <div style={{ width: "100%", height: "100%", backgroundColor: value }} />
162→          </div>
163→          <TextField
164→            label=""
165→            labelHidden
166→            value={value}
167→            onChange={(val) => onChange(val)}
168→            maxLength={7}
169→            autoComplete="off"
170→          />
171→        </InlineStack>
172→      </BlockStack>
173→    </Card>
174→  );
175→}
176→
177→function DisplayModeCard({
178→  value,
179→  label,
180→  description,
181→  benefit,
182→  selected,
183→  onSelect,
184→}: {
185→  value: string;
186→  label: string;
187→  description: string;
188→  benefit: string;
189→  selected: boolean;
190→  onSelect: (v: string) => void;
191→}) {
192→  return (
193→    <div style={{ flex: "1 1 0", minWidth: "140px" }}>
194→      <div role="button" tabIndex={0} onClick={() => onSelect(value)} onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onSelect(value); } }} style={{ cursor: "pointer" }}>
195→        <Box
196→          padding="400"
197→          borderWidth={selected ? "050" : "025"}
198→          borderColor={selected ? "border-focus" : "border"}
199→          borderRadius="200"
200→          background={selected ? "bg-surface-selected" : "bg-surface"}
201→        >
202→          <BlockStack gap="200">
203→            <InlineStack gap="200" blockAlign="center">
204→              <Text as="p" variant="bodyMd" fontWeight="semibold">{label}</Text>
205→              {selected && <Badge tone="info">Active</Badge>}
206→            </InlineStack>
207→            <Text as="p" variant="bodyMd" tone="subdued">{description}</Text>
208→            <Text as="p" variant="bodyMd" tone="subdued">Best for: {benefit}</Text>
209→          </BlockStack>
210→        </Box>
211→      </div>
212→    </div>
213→  );
214→}
215→
216→function PositionGrid({
217→  value,
218→  onChange,
219→}: {
220→  value: string;
221→  onChange: (v: string) => void;
222→}) {
223→  const positions = [
224→    { id: "top-left", label: "Top Left" },
225→    { id: "top-right", label: "Top Right" },
226→    { id: "bottom-left", label: "Bottom Left" },
227→    { id: "bottom-right", label: "Bottom Right" },
228→  ];
229→
230→  return (
231→    <div
232→      style={{
233→        display: "grid",
234→        gridTemplateColumns: "1fr 1fr",
235→        gap: "8px",
236→        maxWidth: "320px",
237→      }}
238→    >
239→      {positions.map((pos) => {
240→        const isSelected = value === pos.id;
241→        return (
242→          <div key={pos.id} role="button" tabIndex={0} onClick={() => onChange(pos.id)} onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onChange(pos.id); } }} style={{ cursor: "pointer" }}>
243→            <Box
244→              padding="400"
245→              borderWidth={isSelected ? "050" : "025"}
246→              borderColor={isSelected ? "border-focus" : "border"}
247→              borderRadius="200"
248→              background={isSelected ? "bg-surface-selected" : "bg-surface"}
249→            >
250→              <Text as="p" variant="bodyMd" tone={isSelected ? undefined : "subdued"}>{pos.label}</Text>
251→            </Box>
252→          </div>
253→        );
254→      })}
255→    </div>
256→  );
257→}
258→
259→function TriggerTypeSelector({
260→  value,
261→  onChange,
262→}: {
263→  value: string;
264→  onChange: (v: string) => void;
265→}) {
266→  const types = [
267→    { id: "button", label: "Button", desc: "Prominent CTA button" },
268→    { id: "link", label: "Link", desc: "Subtle text link" },
269→    { id: "tab", label: "Tab", desc: "Sticky tab on the edge" },
270→  ];
271→
272→  return (
273→    <InlineStack gap="400">
274→      {types.map((t) => {
275→        const isSelected = value === t.id;
276→        return (
277→          <div key={t.id} role="button" tabIndex={0} onClick={() => onChange(t.id)} onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onChange(t.id); } }} style={{ cursor: "pointer" }}>
278→            <Box
279→              padding="400"
280→              borderWidth={isSelected ? "050" : "025"}
281→              borderColor={isSelected ? "border-focus" : "border"}
282→              borderRadius="200"
283→              background={isSelected ? "bg-surface-selected" : "bg-surface"}
284→            >
285→              <BlockStack gap="200">
286→                <Text as="p" variant="bodyMd" fontWeight="semibold">{t.label}</Text>
287→                <Text as="p" variant="bodyMd" tone="subdued">{t.desc}</Text>
288→              </BlockStack>
289→            </Box>
290→          </div>
291→        );
292→      })}
293→    </InlineStack>
294→  );
295→}
296→
297→// ---------------------------------------------------------------------------
298→// Live Preview — intentional custom styling kept as-is
299→// ---------------------------------------------------------------------------
300→
301→function WidgetPreview({ config }: { config: LocalConfig }) {
302→  const radius = `${config.borderRadius}px`;
303→
304→  return (
305→    <div
306→      style={{
307→        backgroundColor: config.backgroundColor,
308→        borderRadius: radius,
309→        border: `1px solid ${config.primaryColor}33`,
310→        padding: "20px",
311→        fontFamily: "system-ui, sans-serif",
312→        boxShadow: "0 4px 16px rgba(0,0,0,0.08)",
313→        maxWidth: "320px",
314→        width: "100%",
315→      }}
316→    >
317→      {/* Header */}
318→      <div
319→        style={{
320→          borderBottom: `1px solid ${config.primaryColor}22`,
321→          paddingBottom: "12px",
322→          marginBottom: "16px",
323→          display: "flex",
324→          alignItems: "center",
325→          justifyContent: "space-between",
326→        }}
327→      >
328→        <span
329→          style={{
330→            fontSize: "16px",
331→            fontWeight: 700,
332→            color: config.textColor,
333→          }}
334→        >
335→          {config.heading || "Size Guide"}
336→        </span>
337→        <span
338→          style={{
339→            fontSize: "18px",
340→            color: "#8c9196",
341→            cursor: "pointer",
342→            lineHeight: 1,
343→          }}
344→        >
345→          ×
346→        </span>
347→      </div>
348→
349→      {/* Size Chart Table */}
350→      <div
351→        style={{
352→          borderRadius: "6px",
353→          overflow: "hidden",
354→          border: "1px solid #e3e5e7",
355→          marginBottom: "16px",
356→        }}
357→      >
