473→// ---------------------------------------------------------------------------
474→// Main Component
475→// ---------------------------------------------------------------------------
476→
477→export default function WidgetCustomizer() {
478→  const { config: serverConfig } = useLoaderData<typeof loader>();
479→  const fetcher = useFetcher<typeof action>();
480→  const shopify = useAppBridge();
481→  const navigate = useNavigate();
482→
483→  const [config, setConfig] = useState<LocalConfig>({
484→    displayMode: serverConfig.displayMode,
485→    position: serverConfig.position,
486→    triggerType: serverConfig.triggerType,
487→    primaryColor: serverConfig.primaryColor,
488→    successColor: serverConfig.successColor,
489→    errorColor: serverConfig.errorColor,
490→    backgroundColor: serverConfig.backgroundColor,
491→    textColor: serverConfig.textColor,
492→    borderRadius: serverConfig.borderRadius,
493→    heading: serverConfig.heading,
494→    placeholder: serverConfig.placeholder,
495→    buttonText: serverConfig.buttonText,
496→    successMessage: serverConfig.successMessage,
497→    errorMessage: serverConfig.errorMessage,
498→    showRecommender: serverConfig.showRecommender,
499→    customCss: serverConfig.customCss,
500→  });
501→
502→  const isLoading = fetcher.state !== "idle";
503→
504→  useEffect(() => {
505→    if (fetcher.data && "ok" in fetcher.data) {
506→      shopify.toast.show(fetcher.data.message ?? "Widget settings saved");
507→    } else if (fetcher.data && "error" in fetcher.data) {
508→      shopify.toast.show(fetcher.data.error ?? "Failed to save settings", { isError: true });
509→    }
510→  }, [fetcher.data, shopify]);
511→
512→  const updateConfig = (key: keyof LocalConfig, value: string | boolean) => {
513→    setConfig((prev) => ({ ...prev, [key]: value }));
514→  };
515→
516→  const handleSave = () => {
517→    const formData = new FormData();
518→    formData.set("displayMode", config.displayMode);
519→    formData.set("position", config.position);
520→    formData.set("triggerType", config.triggerType);
521→    formData.set("primaryColor", config.primaryColor);
522→    formData.set("successColor", config.successColor);
523→    formData.set("errorColor", config.errorColor);
524→    formData.set("backgroundColor", config.backgroundColor);
525→    formData.set("textColor", config.textColor);
526→    formData.set("borderRadius", config.borderRadius);
527→    formData.set("heading", config.heading);
528→    formData.set("placeholder", config.placeholder);
529→    formData.set("buttonText", config.buttonText);
530→    formData.set("successMessage", config.successMessage);
531→    formData.set("errorMessage", config.errorMessage);
532→    formData.set("showRecommender", config.showRecommender ? "true" : "false");
533→    formData.set("customCss", config.customCss);
534→    fetcher.submit(formData, { method: "post" });
535→  };
536→
537→  const showPosition = config.displayMode === "popup" || config.displayMode === "both";
538→
539→  return (
540→    <Page
541→      title="Widget Customizer"
542→      backAction={{ onAction: () => navigate("/app") }}
543→      primaryAction={
544→        <Button variant="primary" onClick={handleSave} loading={isLoading}>
545→          Save changes
546→        </Button>
547→      }
548→    >
549→      <Layout>
550→        <Layout.Section>
551→          <BlockStack gap="600">
552→
553→            {/* ---------------------------------------------------------------- */}
554→            {/* Section 1 — Display Mode                                         */}
555→            {/* ---------------------------------------------------------------- */}
556→            <Card>
557→              <BlockStack gap="400">
558→                <Text as="h2" variant="headingMd" fontWeight="bold">Display Mode</Text>
559→                <InlineStack gap="400" wrap>
560→                  <DisplayModeCard
561→                    value="popup"
562→                    label="Popup"
563→                    description="Opens as a modal overlay when triggered"
564→                    benefit="clean product pages"
565→                    selected={config.displayMode === "popup"}
566→                    onSelect={(v) => updateConfig("displayMode", v)}
567→                  />
568→                  <DisplayModeCard
569→                    value="inline"
570→                    label="Inline"
571→                    description="Embedded directly in the product page"
572→                    benefit="detailed size info"
573→                    selected={config.displayMode === "inline"}
574→                    onSelect={(v) => updateConfig("displayMode", v)}
575→                  />
576→                  <DisplayModeCard
577→                    value="both"
578→                    label="Both"
579→                    description="Inline summary with popup for full chart"
580→                    benefit="maximum visibility"
581→                    selected={config.displayMode === "both"}
582→                    onSelect={(v) => updateConfig("displayMode", v)}
583→                  />
584→                </InlineStack>
585→              </BlockStack>
586→            </Card>
587→
588→            {/* ---------------------------------------------------------------- */}
589→            {/* Section 2 — Trigger Settings                                     */}
590→            {/* ---------------------------------------------------------------- */}
591→            <Card>
592→              <BlockStack gap="400">
593→                <Text as="h2" variant="headingMd" fontWeight="bold">Trigger Settings</Text>
594→                <BlockStack gap="400">
595→                  <BlockStack gap="200">
596→                    <Text as="p" variant="bodyMd">Trigger style</Text>
597→                    <TriggerTypeSelector
598→                      value={config.triggerType}
599→                      onChange={(v) => updateConfig("triggerType", v)}
600→                    />
601→                  </BlockStack>
602→
603→                  {showPosition && (
604→                    <BlockStack gap="200">
605→                      <Text as="p" variant="bodyMd">Popup position</Text>
606→                      <PositionGrid
607→                        value={config.position}
608→                        onChange={(v) => updateConfig("position", v)}
609→                      />
610→                    </BlockStack>
611→                  )}
612→                </BlockStack>
613→              </BlockStack>
614→            </Card>
615→
616→            {/* ---------------------------------------------------------------- */}
617→            {/* Section 3 — Colors                                               */}
618→            {/* ---------------------------------------------------------------- */}
619→            <Card>
620→              <BlockStack gap="400">
621→                <Text as="h2" variant="headingMd" fontWeight="bold">Colors</Text>
622→                <InlineStack gap="400" wrap>
623→                  <ColorPickerField
624→                    label="Primary Color"
625→                    value={config.primaryColor}
626→                    onChange={(v) => updateConfig("primaryColor", v)}
627→                  />
628→                  <ColorPickerField
629→                    label="Background Color"
630→                    value={config.backgroundColor}
631→                    onChange={(v) => updateConfig("backgroundColor", v)}
632→                  />
633→                  <ColorPickerField
634→                    label="Text Color"
635→                    value={config.textColor}
636→                    onChange={(v) => updateConfig("textColor", v)}
637→                  />
638→                  <ColorPickerField
639→                    label="Success Color"
640→                    value={config.successColor}
641→                    onChange={(v) => updateConfig("successColor", v)}
642→                  />
643→                  <ColorPickerField
644→                    label="Error Color"
645→                    value={config.errorColor}
646→                    onChange={(v) => updateConfig("errorColor", v)}
647→                  />
648→                </InlineStack>
649→              </BlockStack>
650→            </Card>
651→
652→            {/* ---------------------------------------------------------------- */}
653→            {/* Section 4 — Typography & Spacing                                 */}
654→            {/* ---------------------------------------------------------------- */}
655→            <Card>
656→              <BlockStack gap="400">
657→                <Text as="h2" variant="headingMd" fontWeight="bold">Typography &amp; Spacing</Text>
658→                <BlockStack gap="200">
659→                  <BlockStack gap="200">
660→                    <Text as="p" variant="bodyMd">Border Radius (px)</Text>
661→                    <InlineStack gap="400" blockAlign="center">
662→                      <div style={{ flex: 1 }}>
663→                        <input
664→                          type="range"
665→                          min="0"
666→                          max="24"
667→                          value={config.borderRadius}
668→                          onChange={(e) => updateConfig("borderRadius", e.target.value)}
669→                          style={{ width: "100%", accentColor: "#005bd3", cursor: "pointer" }}
670→                        />
671→                      </div>
672→                      <input
673→                        type="number"
674→                        min="0"
675→                        max="24"
676→                        value={config.borderRadius}
677→                        onChange={(e) => updateConfig("borderRadius", e.target.value)}
678→                        style={{
